import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#game');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9fe5f5); scene.fog=new THREE.Fog(0x9fe5f5,28,105);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,180);
camera.position.set(0,8.5,15); camera.lookAt(0,1,-12);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight(0xdff8ff,0x8263a8,2.25));
const sun=new THREE.DirectionalLight(0xffefcf,3.2); sun.position.set(-7,15,8); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); scene.add(sun);
const mat=(color,rough=.7,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={road:mat(0x60597e),line:mat(0xfaf0a9),pink:mat(0xff408e,.43),cyan:mat(0x38d9ef,.4),yellow:mat(0xffd344,.4),purple:mat(0x7654d9,.5),white:mat(0xffffff,.5),black:mat(0x191b2b,.45),skin:mat(0xffd0a2),grass:mat(0x75d89e),red:mat(0xf63d62),blue:mat(0x40b8ff),boss:mat(0x48264e,.5)};
const box=(w,h,d,material,x=0,y=0,z=0)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;return m};
// Candy-colored floating highway and scenery
const floor=box(13,.3,190,mats.road,0,-.25,-75); scene.add(floor);
const edges=[box(.28,.18,190,mats.cyan,-6.25,-.02,-75),box(.28,.18,190,mats.pink,6.25,-.02,-75)]; edges.forEach(o=>scene.add(o));
for(let lane=-1;lane<=1;lane++){for(let i=0;i<16;i++){const dash=box(.055,.025,2.2,mat(0xbab4d4),lane*2.15,.0,-i*11-4);scene.add(dash)}}
const scenery=[];
for(let i=0;i<30;i++){const z=-i*7-8, side=i%2?1:-1;const h=2+Math.random()*5;const tower=box(1.5+Math.random()*1.7,h,1.3,[mat(0xff85ad),mat(0x77ddf3),mat(0xffd468),mat(0x9f87ec)][i%4],side*(9+Math.random()*8),h/2-.2,z);scene.add(tower);scenery.push(tower);const cap=box(.7,.12,.08,mats.white,tower.position.x,tower.position.y+h*.15,z+.68);scene.add(cap);scenery.push(cap)}
// Floating silly UI-shaped billboards
function textSprite(text,bg='#ffdc4c',fg='#31214c',size=30){const c=document.createElement('canvas');c.width=512;c.height=180;const x=c.getContext('2d');x.fillStyle=bg;x.beginPath();x.roundRect(8,8,496,164,34);x.fill();x.strokeStyle='white';x.lineWidth=8;x.stroke();x.fillStyle=fg;x.font=`900 ${size}px sans-serif`;x.textAlign='center';x.textBaseline='middle';x.fillText(text,256,91);const tex=new THREE.CanvasTexture(c);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true}));sprite.scale.set(5,1.75,1);return sprite}
for(let i=0;i<8;i++){const sign=textSprite(['5★ GAME!','LIMITED TIME!','NO ADS*','FREE GEMS!'][i%4],i%2?'#ff5097':'#ffe34f');sign.position.set(i%2?-8:8,5,-18-i*18);scene.add(sign);scenery.push(sign)}
// Player stickpeople
function makeStick(color=0x20243c,scale=1){const g=new THREE.Group();const dark=new THREE.MeshStandardMaterial({color,roughness:.43});const head=new THREE.Mesh(new THREE.SphereGeometry(.22,16,12),mats.skin);head.position.y=1.67;head.castShadow=true;g.add(head);const torso=box(.17,.62,.16,dark,0,1.18,0);g.add(torso);
function limb(a,b,r=.075){const d=new THREE.Vector3().subVectors(b,a),mesh=new THREE.Mesh(new THREE.CylinderGeometry(r*.75,r,d.length(),8),dark);mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());mesh.castShadow=true;g.add(mesh)}
limb(new THREE.Vector3(0,1.42,0),new THREE.Vector3(-.34,1.08,0));limb(new THREE.Vector3(0,1.42,0),new THREE.Vector3(.34,1.08,0));limb(new THREE.Vector3(-.06,.9,0),new THREE.Vector3(-.22,.25,0),.09);limb(new THREE.Vector3(.06,.9,0),new THREE.Vector3(.22,.25,0),.09);g.scale.setScalar(scale);return g}
const player=makeStick();player.position.set(0,0,3.7);scene.add(player);
let squadVisuals=[];let squad=1;function rebuildSquad(){squadVisuals.forEach(x=>scene.remove(x));squadVisuals=[];const shown=Math.min(squad,28);for(let i=0;i<shown;i++){if(i===0){squadVisuals.push(player);continue}const clone=makeStick(i%4===0?0x35205e:0x20243c,.82);const row=Math.ceil(i/5),col=(i-1)%5;clone.position.set((col-2)*.78,0,player.position.z+row*.72);scene.add(clone);squadVisuals.push(clone)}}
// Build gates / hazards using explicit world distance positions
const gateDistances=[12,25,38,51,64,77,90,103];const gates=[];
function makeGate(distance,index){const g=new THREE.Group();g.userData={distance,index,done:false};const bars=[-2.25,2.25];bars.forEach((x,j)=>{const color=j===0?0x45e6d7:0xff4c94;const post=box(.15,3.0,.2,mat(color,.35,.15),x,1.5,0);g.add(post);const board=box(2.15,.94,.25,mat(j===0?0x34cfbf:0xff478f,.32),x,2.58,0);g.add(board);const label=textSprite(index%3===0?(j===0?'×2':'−3'):(j===0?'+5':'×2'),j===0?'#29cabd':'#fa4387','#fff',47);label.scale.set(1.8,.72,1);label.position.set(x,2.59,.18);g.add(label);});const top=box(4.65,.17,.22,mats.yellow,0,3.14,0);g.add(top);g.position.z=3.7-distance;scene.add(g);gates.push(g)}
gateDistances.forEach((d,i)=>makeGate(d,i));
const hazards=[];[19,45,71,97].forEach((d,i)=>{const h=new THREE.Group();h.userData={distance:d,done:false,lane:i%2?2.4:-2.4};const base=box(1.2,.7,.8,i%2?mats.red:mats.purple,0,.35,0);h.add(base);const cone=new THREE.Mesh(new THREE.ConeGeometry(.68,.75,5),mats.yellow);cone.position.y=1.05;cone.castShadow=true;h.add(cone);h.position.set(h.userData.lane,0,3.7-d);scene.add(h);hazards.push(h)});
// Boss at finish line
const boss=new THREE.Group();boss.position.set(0,0,3.7-116);scene.add(boss);boss.add(box(2.2,2.2,1.2,mats.boss,0,1.2,0));const bossHead=new THREE.Mesh(new THREE.SphereGeometry(.73,24,18),mat(0xd44272));bossHead.position.y=2.95;bossHead.castShadow=true;boss.add(bossHead);boss.add(box(1.1,.22,.11,mats.yellow,0,3.05,.68));boss.add(box(.42,.12,.12,mats.black,0,2.52,.68));for(const x of [-1.25,1.25]){const arm=box(.38,1.65,.4,mats.boss,x,1.4,0);arm.rotation.z=x<0?-.2:.2;boss.add(arm)}const bossTitle=textSprite('PAYWALL BOSS','#42203f','#fff',40);bossTitle.scale.set(4,1.35,1);bossTitle.position.set(0,4.7,0);boss.add(bossTitle);
// State, controls and UI
let state='intro',level=1,progress=0,lane=0,cash=240,bossHp=100,runSpeed=9,moveTarget=0,shopBoost=0,soundOn=true,toastTimer=0,attackPower=1;
const $=s=>document.querySelector(s), setCash=n=>{$('#cash').textContent=Math.floor(cash=n)}, ui={intro:$('#intro'),shop:$('#shop'),result:$('#result'),hud:$('#runHud'),boss:$('#bossHud'),tap:$('#tapZone')};
function showToast(t){const el=$('#toast');el.textContent=t;el.style.opacity=1;el.style.transform='translate(-50%,-50%) scale(1.12)';toastTimer=1.05}
function levelText(){$('#level').textContent=String(level).padStart(2,'0')}
function startRun(){state='run';progress=0;lane=0;moveTarget=0;bossHp=100;squad=1+shopBoost;shopBoost=0;rebuildSquad();ui.intro.classList.add('hidden');ui.shop.classList.add('hidden');ui.result.classList.add('hidden');ui.boss.classList.add('hidden');ui.tap.classList.add('hidden');ui.hud.classList.remove('hidden');$('#bottomHint').classList.remove('hidden');$('#progressBar').style.width='0%';$('#progressText').textContent='0%';levelText();gates.forEach((g,i)=>{g.userData.done=false;g.position.z=3.7-g.userData.distance});hazards.forEach(h=>{h.userData.done=false;h.position.z=3.7-h.userData.distance});boss.position.z=3.7-116;player.position.x=0;runSpeed=8.3+Math.min(level-1,8)*.55;}
function showShop(){state='shop';ui.intro.classList.add('hidden');ui.shop.classList.remove('hidden');ui.result.classList.add('hidden');ui.hud.classList.add('hidden');$('#bottomHint').classList.add('hidden');levelText()}
function showResult(win){state='result';ui.boss.classList.add('hidden');ui.tap.classList.add('hidden');$('#result').classList.remove('hidden');$('#resultTitle').innerHTML=win?'BOSS<br><span>DEFEATED!</span>':'SQUAD<br><span>WIPED OUT!</span>';$('#resultEyebrow').innerHTML=win?'<i></i> CONGRATS, YOU BEAT THE ALGORITHM <i></i>':'<i></i> VERY ENGAGING GAMEPLAY <i></i>';$('#resultText').textContent=win?'Against all odds, you survived the monetization.':'The boss has reviewed your performance.';$('#reward').textContent=win?Math.floor(70+level*18):Math.floor(25+level*7);$('#nextBtn').textContent=win?'CLAIM & NEXT LEVEL':'CLAIM YOUR CONSOLATION';$('#result').classList.remove('hidden')}
function move(dir){if(state!=='run')return;moveTarget=THREE.MathUtils.clamp(moveTarget+dir*2.15,-4.2,4.2)}
function chooseGate(g){if(g.userData.done)return;g.userData.done=true;const lanePick=Math.abs(player.position.x+2.25)<Math.abs(player.position.x-2.25)?0:1;let gain;if(g.userData.index%3===0)gain=lanePick===0?Math.max(1,squad): -3;else gain=lanePick===0?5:Math.max(squad,2);if(gain<0){squad=Math.max(1,squad+gain);showToast('−3 CLONES!')}else{if(g.userData.index%3===0&&lanePick===0)squad=Math.min(999,squad*2);else squad=Math.min(999,squad+gain);showToast(g.userData.index%3===0&&lanePick===0?'SQUAD ×2!':`+${gain} CLONES!`)}rebuildSquad();setCash(cash+Math.max(2,Math.floor(squad*.7)));}
function attack(){if(state!=='boss')return;const damage=Math.max(1,squad*.55);bossHp=Math.max(0,bossHp-damage);$('#bossHealth').style.width=bossHp+'%';$('#bossHpText').textContent=Math.ceil(bossHp)+'%';boss.rotation.y=Math.sin(performance.now()*.02)*.12;boss.scale.setScalar(1+Math.random()*.045);if(bossHp<=0){setCash(cash+50+level*5);showResult(true)}}
$('#playBtn').onclick=showShop;$('#continueBtn').onclick=startRun;$('#skipShop').onclick=startRun;$('#nextBtn').onclick=()=>{cash+=Number($('#reward').textContent);level++;levelText();$('#result').classList.add('hidden');showShop()};$('#retryBtn').onclick=()=>{levelText();$('#result').classList.add('hidden');showShop()};$('#bannerShop').onclick=()=>{if(state==='run')showToast('THE SHOP IS NEVER CLOSED!');else showShop()};$('#freeCash').onclick=()=>{setCash(cash+10);showToast('+¢10 FREE*')};$('#soundBtn').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';showToast(soundOn?'SOUND ON':'SOUND OFF')};document.querySelectorAll('.shop-item').forEach(button=>button.onclick=()=>{const cost=button.dataset.item==='squad'?75:100;if(cash<cost){showToast('NOT ENOUGH CASH!');return}setCash(cash-cost);if(button.dataset.item==='squad'){squad+=5;shopBoost+=5}else shopBoost+=3;button.classList.add('selected');showToast('PURCHASED!')});
$('#leftBtn').onclick=()=>move(-1);$('#rightBtn').onclick=()=>move(1);$('#tapZone').addEventListener('pointerdown',attack);window.addEventListener('keydown',e=>{if(['ArrowLeft','a','A'].includes(e.key))move(-1);if(['ArrowRight','d','D'].includes(e.key))move(1);if(state==='boss'&&(e.key===' '||e.key==='Enter'))attack()});let pointerX=null;canvas.addEventListener('pointerdown',e=>{pointerX=e.clientX});canvas.addEventListener('pointerup',e=>{if(pointerX===null)return;const dx=e.clientX-pointerX;if(Math.abs(dx)>24)move(dx>0?1:-1);pointerX=null});
let prev=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-prev)/1000);prev=now;if(state==='run'){progress+=runSpeed*dt;player.position.x=THREE.MathUtils.damp(player.position.x,moveTarget,8,dt);player.rotation.z=THREE.MathUtils.damp(player.rotation.z,-(moveTarget-player.position.x)*.07,6,dt);player.position.y=Math.abs(Math.sin(now*.012))*.055;for(const clone of squadVisuals){if(clone!==player){clone.position.z=player.position.z+Math.ceil((squadVisuals.indexOf(clone))/5)*.72;clone.position.x=THREE.MathUtils.damp(clone.position.x,player.position.x+( ((squadVisuals.indexOf(clone)-1)%5)-2)*.78,6,dt)}}gates.forEach(g=>{g.position.z=3.7-g.userData.distance+progress;if(!g.userData.done&&g.position.z>2.9)chooseGate(g)});hazards.forEach(h=>{h.position.z=3.7-h.userData.distance+progress;if(!h.userData.done&&h.position.z>2.6){h.userData.done=true;if(Math.abs(player.position.x-h.userData.lane)<1.55){squad=Math.max(1,squad-Math.min(squad-1,Math.ceil(level*.5)));rebuildSquad();showToast('OUCH! CLONES LOST');}}});scenery.forEach(o=>{o.position.z+=runSpeed*dt;if(o.position.z>17)o.position.z-=210});const pct=Math.min(100,progress/116*100);$('#progressBar').style.width=pct+'%';$('#progressText').textContent=Math.floor(pct)+'%';if(progress>115){state='boss';ui.boss.classList.remove('hidden');ui.tap.classList.remove('hidden');$('#bottomHint').classList.add('hidden');$('#bossName').textContent=['THE PAYWALL','AD WIZARD','MEGA WHALE'][Math.min(2,Math.floor((level-1)/2))];$('#bossHealth').style.width='100%';$('#bossHpText').textContent='100%';showToast('FINAL BOSS!')}}else if(state==='boss'){boss.position.z=3.7-116+Math.sin(now*.002)*.14;boss.rotation.y=Math.sin(now*.0018)*.08;}
if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0){$('#toast').style.opacity=0;$('#toast').style.transform='translate(-50%,-50%) scale(.8)'}}renderer.render(scene,camera)}requestAnimationFrame(animate);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2))});

